fn is_happy(s: Vec<char>) -> bool {
    // A happy sequence must be at least length 3
    if s.len() < 3 {
        return false;
    }

    // Slide a window of size 3 over the sequence
    for window in s.windows(3) {
        // Check that all three characters in the window are pairwise distinct
        if window[0] == window[1] || window[0] == window[2] || window[1] == window[2] {
            return false;
        }
    }

    true
}

